import gurobipy as gp

# Data from parameters
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [25, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]   # cost[origin][destination][product]

n_origins = len(supply)
n_destinations = len(demand[0]) if demand else 0
n_products = len(supply[0]) if supply else 0

model = gp.Model(env=env)   # runtime-provided environment

# Variables x[i][j][p] continuous >=0
x = {}
for i in range(n_origins):
    for j in range(n_destinations):
        for p in range(n_products):
            x[(i, j, p)] = model.addVar(type=gp.GRB.CONTINUOUS, name=f"x_{i}_{j}_{p}")

# Supply balance constraints
for i in range(n_origins):
    for p in range(n_products):
        expr = gp.quicksum([x[(i, j, p)] for j in range(n_destinations)])
        model.addConstr(expr == supply[i][p], name=f"supply_{i}_{p}")

# Demand balance constraints
for j in range(n_destinations):
    for p in range(n_products):
        expr = gp.quicksum([x[(i, j, p)] for i in range(n_origins)])
        model.addConstr(expr == demand[j][p], name=f"demand_{j}_{p}")

# Origin-destination limit constraints
for i in range(n_origins):
    for j in range(n_destinations):
        expr = gp.quicksum([x[(i, j, p)] for p in range(n_products)])
        model.addConstr(expr <= limit[i][j], name=f"limit_{i}_{j}")

# Objective: minimize total shipping cost
obj_expr = gp.quicksum([cost[i][j][p] * x[(i, j, p)] for i in range(n_origins)
                         for j in range(n_destinations)
                         for p in range(n_products)])
model.setObjective(obj_expr, gp.GRB.MINIMIZE)

# Optimize
model.optimize()

if model.Status == gp.GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal}")
