from gurobipy import GRB

# Assume env is provided externally
model = gp.Model(env=env)

# Data from parameters
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [25, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

# Decision variables x[i][j][p] continuous >=0
x = {}
for i in range(2):
    for j in range(2):
        for p in range(2):
            var_name = f"x_{i}_{j}_{p}"
            x[(i, j, p)] = model.addVar(lb=0, vtype=GRB.CONTINUOUS, name=var_name)

# Supply balance: Σ_j x_{i,j,p} = supply[i][p]
for i in range(2):
    for p in range(2):
        expr = gp.LinExpr()
        for j in range(2):
            expr += x[(i, j, p)]
        model.addConstr(expr == supply[i][p], name=f"supply_bal_{i}_{p}")

# Demand balance: Σ_i x_{i,j,p} = demand[j][p]
for j in range(2):
    for p in range(2):
        expr = gp.LinExpr()
        for i in range(2):
            expr += x[(i, j, p)]
        model.addConstr(expr == demand[j][p], name=f"demand_bal_{j}_{p}")

# Capacity limit: Σ_p x_{i,j,p} ≤ limit[i][j]
for i in range(2):
    for j in range(2):
        expr = gp.LinExpr()
        for p in range(2):
            expr += x[(i, j, p)]
        model.addConstr(expr <= limit[i][j], name=f"limit_{i}_{j}")

# Objective: minimize total shipping cost Σ_i Σ_j Σ_p cost[i][j][p] * x_{i,j,p}
obj_expr = gp.LinExpr()
for i in range(2):
    for j in range(2):
        for p in range(2):
            obj_expr += cost[i][j][p] * x[(i, j, p)]
model.setObjective(obj_expr, GRB.MINIMIZE)

# Optimize
model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
